  function incidentCommand(root){
    const r=BSC.state.ransomware||{}, hosts=r.hosts||[], imp=r.impact||{}, rec=r.recovery||{};
    const affected=hosts.filter(x=>['Compromised','Encrypting','Degraded','Targeted','Attack blocked'].includes(x.status)).length;
    const contained=hosts.filter(x=>x.status==='Contained').length;
    const severity=r.incidentDeclared?'SEV-1':'UNDECLARED';
    root.innerHTML=shell('MAJOR INCIDENT COMMAND',['Situation','Command','Blast radius','Containment','Eradication','Recovery','Communications','Decision log'],`
      <div class="app-head"><div><h2>BLACK FROST · Ransomware Major Incident</h2><p>Resposta coordenada. Cada minuto gasto em outras tarefas pode alterar o blast radius enquanto o incidente estiver ativo.</p></div>${openTicket('SEC-2026-0077')}</div>
      <div class="ransom-banner ${r.contained?'contained':r.stage==='major-impact'?'critical':''}"><div><b>${h(severity)} · ${h((r.stage||'watch').toUpperCase())}</b><span>${r.active?`Outbreak clock ${r.elapsed||0} min`:'Signal waiting for confirmation'}</span></div><div>${tag(`${affected} affected`,'critical')} ${tag(`${contained} contained`,contained?'pass':'open')} ${tag(`${imp.encryptedFiles||0} encrypted files`,'high')}</div></div>
      <div class="grid2"><div class="card"><div class="split"><h3>INCIDENT COMMAND</h3>${tag(r.warRoom?'WAR ROOM ACTIVE':'NO WAR ROOM',r.warRoom?'pass':'warning')}</div>
        <table class="table"><tr><td>Incident</td><td>SEC-2026-0077</td></tr><tr><td>Incident Commander</td><td>${r.incidentDeclared?'Diego Rocha · DFIR Lead':'Not assigned'}</td></tr><tr><td>Patient zero</td><td>${h(r.patientZero||'-')}</td></tr><tr><td>Compromised identity</td><td>${h(r.compromisedIdentity||'-')}</td></tr><tr><td>Business impact</td><td>${h(imp.businessImpact||'-')}</td></tr><tr><td>Unavailable</td><td>${h((imp.unavailableServices||[]).join(', ')||'None confirmed')}</td></tr></table>
        <div class="toolbar"><button class="btn accent" data-ransom-start ${r.active?'disabled':''}>Confirm ransomware signal</button><button class="btn danger" data-ransom-declare ${r.incidentDeclared?'disabled':''}>Declare SEV-1 + War Room</button><button class="btn" data-ransom-scope>Build blast-radius view</button></div>
      </div><div class="card"><h3>RESPONSE GATES</h3>
        <div class="ir-gates">
          ${[['Detect',r.active],['Declare',r.incidentDeclared],['Scope',!!BSC.state.completedObjectives.ransom_scope_mapped],['Identity',r.credentialRevoked],['Network',r.networkSegmented],['Backup',r.backupProtected],['Hosts',!!BSC.state.completedObjectives.ransom_hosts_contained],['Eradicate',r.eradicated],['Recover',r.recoveryValidated],['Comms',!!BSC.state.completedObjectives.ransom_comms_done]].map(([n,v])=>`<div class="ir-gate ${v?'done':''}"><span>${v?'✓':'·'}</span><b>${n}</b></div>`).join('')}
        </div>
        <div class="toolbar" style="margin-top:12px"><button class="btn" data-open="soc">SIEM</button><button class="btn" data-open="ndr">NDR</button><button class="btn" data-open="xdr">XDR</button><button class="btn" data-open="iam">IAM</button><button class="btn" data-open="backup">Backup</button><button class="btn" data-open="dfir">DFIR</button></div>
      </div></div>
      <div class="card" style="margin-top:12px"><div class="split"><h3>BLAST RADIUS / HOST STATE</h3><span class="muted">state changes as the shift clock advances</span></div><div class="blast-grid">${hosts.map(x=>`<article class="blast-host ${String(x.status).toLowerCase().replace(/\s+/g,'-')}"><header><b>${h(x.id)}</b>${tag(x.status,['Encrypting','Compromised','Degraded'].includes(x.status)?'critical':x.status==='Contained'||x.status==='Recovered'||x.status==='Protected'?'pass':'warning')}</header><p>${h(x.role)} · ${h(x.vector)}</p><small>${x.encrypted||0} files affected · ${h(x.criticality)}</small></article>`).join('')}</div></div>
      <div class="grid2" style="margin-top:12px"><div class="card"><h3>IR TIMELINE</h3><div class="incident-timeline">${(r.timeline||[]).slice().reverse().map(x=>`<div><time>${h(x.time)}</time><span><b>${h(x.type)}</b><br>${h(x.detail)}</span></div>`).join('')}</div></div>
      <div class="card"><h3>ERADICATION & RECOVERY</h3><p class="muted">Recovery before containment is intentionally allowed — and assessed.</p><div class="toolbar"><button class="btn danger" data-ransom-eradicate ${r.eradicated?'disabled':''}>Run eradication gate</button><button class="btn" data-ransom-cleanroom ${rec.cleanRoom?'disabled':''}>Create clean room</button><button class="btn success" data-ransom-restore ${rec.restoreComplete?'disabled':''}>Restore FILE-HR-01</button><button class="btn" data-ransom-validate ${r.recoveryValidated?'disabled':''}>Validate AD + files + business</button></div><div class="timeline-note" style="margin-top:10px">Restore point: <b>${h(rec.selectedRestorePoint||'not selected')}</b><br>Clean room: <b>${rec.cleanRoom?'READY':'NO'}</b> · Restore: <b>${rec.restoreComplete?'COMPLETE':rec.restoreStarted?'RUNNING':'NOT STARTED'}</b></div><h3 style="margin-top:14px">COMMUNICATIONS</h3><div class="toolbar"><button class="btn" data-ransom-exec>Executive update</button><button class="btn" data-ransom-legal>Legal / Privacy assessment</button><button class="btn accent" data-ransom-lessons>Start RCA / lessons learned</button></div></div></div>
    `);
  }

  function performance(root){
    const missions=BSC_DATA.missions.map(m=>{const[d,t]=BSC.missionProgress(m.id);return{...m,d,t,p:t?d/t:0}});
    const total=missions.reduce((a,m)=>a+m.t,0),done=missions.reduce((a,m)=>a+m.d,0),pct=total?Math.round(done/total*100):0;
    const skills={}; missions.forEach(m=>m.skills.forEach(k=>{skills[k]=skills[k]||{sum:0,n:0};skills[k].sum+=m.p;skills[k].n++}));
    const ranked=Object.entries(skills).map(([k,v])=>[k,Math.round(v.sum/v.n*100)]).sort((a,b)=>b[1]-a[1]);
    const top=ranked.slice(0,3).map(x=>x[0]).join(' / ')||'Em observação';
    root.innerHTML=shell('MY PERFORMANCE',['Executive view','Missions','Skills','Gaps','Audit trail','Assessment PDF'],`
      <div class="app-head"><div><h2>Professional Assessment</h2><p>Avaliação silenciosa baseada em trabalho realizado, sequência, evidência e impacto.</p></div><button class="btn accent" data-report-download>Download colorful PDF</button></div>
      <div class="kpi-grid"><div class="kpi"><span>ACTIONS</span><strong>${BSC.state.audit.length}</strong></div><div class="kpi"><span>OBJECTIVES</span><strong>${done}/${total}</strong></div><div class="kpi"><span>PROGRESS</span><strong>${pct}%</strong></div><div class="kpi"><span>GAPS</span><strong class="${BSC.state.gaps.length?'warning':'ok'}">${BSC.state.gaps.length}</strong></div></div>
      <div class="card"><div class="split"><h3>OBSERVED PROFILE</h3>${tag(top,'pass')}</div><div class="metric-bars">${ranked.map(([k,v])=>`<div class="metric-row"><span>${h(k)}</span><div class="bar"><i style="width:${v}%"></i></div><b>${v}%</b></div>`).join('')}</div></div>
      <div class="grid2" style="margin-top:12px"><div class="card"><h3>MISSIONS</h3>${missions.map(m=>`<div class="metric-row"><span>${h(m.id)} ${h(m.title.slice(0,24))}</span><div class="bar"><i style="width:${m.p*100}%"></i></div><b>${m.d}/${m.t}</b></div>`).join('')}</div><div class="card"><h3>GAPS & COACHING</h3>${BSC.state.gaps.map(g=>`<div class="gap-card ${g.severity.toLowerCase()}"><strong>${h(g.severity)} · ${h(g.title)}</strong><p>${h(g.detail)}</p><small>${h(g.corpTime)}</small></div>`).join('')||'<div class="empty">Nenhum gap registrado até agora.</div>'}</div></div>
      <div class="card" style="margin-top:12px"><h3>RECENT AUDIT TRAIL</h3><table class="table"><tr><th>TIME</th><th>ACTION</th><th>DETAIL</th></tr>${BSC.state.audit.slice(-40).reverse().map(a=>`<tr><td>${h(a.corpTime)}</td><td>${h(a.action)}</td><td class="mono">${h(JSON.stringify(a.payload).slice(0,150))}</td></tr>`).join('')}</table></div>`);
  }

  const funcs={cloud,waf,ndr,dlp,pam,backup,dfir,detections,purple,grc,datacenter,clients,appsec,attack,ir:incidentCommand,report:performance};

  function attackCommand(cmd){
    const r=BSC.state.redteam,lc=cmd.trim().toLowerCase(); let out='Unknown simulator command. Type help.';
    if(lc==='help')out='scope | recon | scan portal.besafecorp.inc | inspect /legacy-support | simulate-foothold | whoami | routes | pivot jump-adm-01 | access management | dc-map | handoff-blue | report';
    else if(lc==='scope'){out='AUTHORIZED: portal.besafecorp.inc, synthetic DMZ, jump zone, DC management simulation.\nPROHIBITED: real Internet, third parties, destructive actions.';BSC.objective('attack_scope_read');}
    else if(lc==='recon'){r.discovered=['portal.besafecorp.inc','vpn.besafecorp.inc','status.besafecorp.inc'];out='3 synthetic public services discovered. portal.besafecorp.inc exposes HTTPS only.';BSC.objective('attack_surface_mapped');audit('red_recon',{minutes:7});}
    else if(lc==='scan portal.besafecorp.inc'){if(!r.discovered.includes('/legacy-support'))r.discovered.push('/legacy-support');out='Synthetic service map: HTTPS/443 → WAF-01 → WEB-DMZ-01\nInteresting route exposed by training engine: /legacy-support';pushLog({ts:BSC.clock(),source:'waf',host:'WAF-01',event:'sim_recon',user:'-',src:'198.18.10.77',dst:'172.16.10.20',message:'AUTHORIZED RANGE EVENT: path enumeration from Glasshouse simulator'});}
    else if(lc==='inspect /legacy-support'){out='Training finding: legacy support route uses a simulated weak trust boundary. The range permits a non-destructive foothold token for this exercise.';}
    else if(lc==='simulate-foothold'){if(!BSC.state.completedObjectives.attack_scope_read){out='Denied by range engine: acknowledge scope first.';}else{r.stage='dmz';r.session='svc-web@WEB-DMZ-01';out='SIMULATED FOOTHOLD GRANTED on WEB-DMZ-01 as svc-web. No real exploit executed.';BSC.objective('sim_foothold');pushLog({ts:BSC.clock(),source:'web',host:'WEB-DMZ-01',event:'sim_foothold',user:'svc-web',src:'198.18.10.77',dst:'172.16.10.20',message:'AUTHORIZED RANGE EVENT: foothold simulation token granted'});audit('red_foothold',{asset:'WEB-DMZ-01',minutes:12});}}
    else if(lc==='whoami')out=r.session||'glasshouse-external';
    else if(lc==='routes'){out=r.stage==='outside'?'No internal routes. Establish authorized foothold first.':'172.16.10.0/24 DMZ\n10.60.10.0/24 ADMIN-JUMP (reachable through simulated app trust)\n10.255.10.0/24 MGMT (not directly reachable)';}
    else if(lc==='pivot jump-adm-01'){if(r.stage!=='dmz')out='Pivot condition not met.';else{r.stage='jump';r.session='svc-web@JUMP-ADM-01(simulated)';out='SIMULATED PIVOT: WEB-DMZ-01 → JUMP-ADM-01. NDR and identity telemetry generated.';BSC.objective('sim_pivot');pushLog({ts:BSC.clock(),source:'ndr',host:'NDR-SENSOR-01',event:'sim_pivot',user:'svc-web',src:'172.16.10.20',dst:'10.60.10.20',message:'AUTHORIZED RANGE EVENT: DMZ-to-jump lateral path'});audit('red_pivot',{from:'WEB-DMZ-01',to:'JUMP-ADM-01',minutes:15});}}
    else if(lc==='access management'){if(r.stage!=='jump')out='Management zone is not reachable from current stage.';else{r.stage='mgmt';out='MANAGEMENT ZONE REACHED (SIMULATION). Assets visible: BSC-FW-A, BSC-FW-B, CORE-SW-01. No configuration changed.';BSC.objective('sim_dc_access');pushLog({ts:BSC.clock(),source:'firewall',host:'BSC-FW-A',event:'sim_mgmt_access',user:'svc-web',src:'10.60.10.20',dst:'10.255.10.11',message:'AUTHORIZED RANGE EVENT: simulated access to management plane'});audit('red_mgmt_access',{minutes:12});}}
    else if(lc==='dc-map'){out=r.stage==='mgmt'?'R03 Network/Security: CORE-SW-01, CORE-SW-02, BSC-FW-A/B, NDR-SENSOR-01\nR07 Identity/Management: DC01, JUMP-ADM-01, SIEM-01\nR12 Apps/Data: APP-PROD-01, DB-PROD-01, BKP-CTRL-01, BSC-IMM-01':'Datacenter map requires simulated management-zone access.';}
    else if(lc==='handoff-blue'){if(r.stage!=='mgmt')out='Complete simulated path first.';else{r.stage='handoff';out='Blue Team handoff created. Now pivot to SIEM/NDR/Datacenter apps and locate Glasshouse telemetry.';BSC.notify('Purple Team handoff','Operation Glasshouse reached management zone. Hunt the injected telemetry in SIEM/NDR.','soc');audit('red_blue_handoff',{minutes:3});}}
    else if(lc==='report'){if(r.stage!=='handoff')out='Blue handoff required before report.';else if(!BSC.state.completedObjectives.attack_blue_handoff)out='Before reporting, hunt the injected sim_* telemetry in SOC/SIEM and confirm the defensive trail.';else{r.stage='reported';out='Finding registered: public legacy route enabled synthetic trust-boundary path DMZ → jump → management. Recommended controls: remove legacy route, enforce PAM-only administration, segment jump trust, correlate WAF/NDR/PAM.';BSC.objective('attack_reported');audit('red_report',{finding:'Legacy route trust path',minutes:8});}}
    r.history.push({cmd,out,time:BSC.clock()});BSC.save();return out;
  }

