    root.querySelectorAll('[data-ent-open-ticket]').forEach(b=>b.onclick=()=>BSCUI.openApp('itsm',{ticket:b.dataset.entOpenTicket}));
    root.querySelector('[data-ransom-start]')?.addEventListener('click',()=>{BSC.startRansomware();BSC.objective('ransomware_signal_reviewed');audit('ransomware_confirmed',{family:'BLACK FROST',patientZero:'WS-HR-019',minutes:4});incidentCommand(root);});
    root.querySelector('[data-ransom-declare]')?.addEventListener('click',()=>{const r=BSC.state.ransomware;if(!r.active)BSC.startRansomware();r.incidentDeclared=true;r.warRoom=true;r.decisions.severity='SEV-1';BSC.objective('major_incident_declared');audit('major_incident_declared',{severity:'SEV-1',commander:'Diego Rocha',bridge:'Incident War Room',minutes:4});const ch=BSC.state.chats.teams.find(c=>c.channel==='Incident War Room');if(ch)ch.messages.push({time:BSC.clock(),from:'Diego Rocha',text:'BLACK FROST declared SEV-1. Freeze nonessential changes. Work from facts: scope, identities, network, backup, evidence and business impact.'});BSC.notify('SEV-1 declared','Incident War Room activated. Nonessential production changes frozen.','teams');incidentCommand(root);});
    root.querySelector('[data-ransom-scope]')?.addEventListener('click',()=>{if(!BSC.state.ransomware.active)BSC.startRansomware();BSC.state.lastSiemQuery='svc-hr-sync FILE-HR-01';BSC.objective('ransom_scope_mapped');audit('ransom_blast_radius_query',{sources:['SIEM','NDR','XDR','IAM'],hosts:BSC.state.ransomware.hosts.filter(x=>x.status!=='At risk'&&x.status!=='Protected').map(x=>x.id),minutes:7});BSCUI.openApp('soc');});
    root.querySelector('[data-ransom-eradicate]')?.addEventListener('click',()=>{const r=BSC.state.ransomware;if(!(r.credentialRevoked&&r.networkSegmented&&BSC.state.completedObjectives.ransom_hosts_contained)){BSC.gap('eradication_before_containment','Erradicação iniciada antes do containment gate','Processos e persistência foram tratados enquanto identidade, rede ou hosts ainda permitiam reinfecção.','High');BSC.notify('Eradication gate failed','Contain identity, network and affected hosts before declaring eradication.','ir');return;}r.eradicated=true;r.active=false;r.contained=true;r.stage='eradicated';r.decisions.eradication='Persistence removed; compromised credentials rotated; malicious binaries quarantined';r.timeline.push({time:BSC.clock(),type:'Eradication',detail:'Persistence checks completed across affected hosts; compromised identity invalidated; indicators swept across estate.'});BSC.objective('ransom_eradicated');audit('ransomware_eradicated',{hosts:r.hosts.filter(x=>['Contained','Compromised','Encrypting'].includes(x.status)).map(x=>x.id),minutes:18});incidentCommand(root);});
    root.querySelector('[data-ransom-cleanroom]')?.addEventListener('click',()=>{const r=BSC.state.ransomware;if(!r.eradicated)BSC.gap('cleanroom_before_eradication','Clean room iniciado cedo demais','A recuperação foi preparada antes de concluir erradicação e validar que o ambiente não reinfectaria os sistemas restaurados.','Medium');r.recovery.cleanRoom=true;r.recovery.adHealth=true;audit('recovery_clean_room_created',{network:'RECOVERY-VLAN-901',identity:'isolated recovery admin',minutes:12});incidentCommand(root);});
    root.querySelector('[data-ransom-restore]')?.addEventListener('click',()=>{const r=BSC.state.ransomware;if(!BSC.state.completedObjectives.restore_point_validated)BSC.gap('restore_without_validation','Restore iniciado sem validar recovery point','O ponto de restauração não tinha sido montado e verificado antes do restore.','High');if(!r.recovery.cleanRoom)BSC.gap('restore_without_cleanroom','Restore direto em produção','O sistema foi restaurado sem ambiente limpo/segmentado para validar integridade e evitar reinfecção.','High');r.recovery.restoreStarted=true;r.recovery.restoreComplete=true;r.recovery.selectedRestorePoint=r.recovery.selectedRestorePoint||'FILE-HR-01 @ 09:00';const f=r.hosts.find(x=>x.id==='FILE-HR-01');if(f)f.status='Recovered';r.timeline.push({time:BSC.clock(),type:'Recovery',detail:'FILE-HR-01 restored from validated immutable copy into recovery network.'});audit('ransom_restore_completed',{workload:'FILE-HR-01',restorePoint:r.recovery.selectedRestorePoint,minutes:24});incidentCommand(root);});
